package dev.halloween;
import java.util.*;
import net.fabricmc.fabric.api.event.lifecycle.v1.ServerTickEvents;
import net.minecraft.entity.*;
import net.minecraft.entity.passive.VillagerEntity;
import net.minecraft.server.world.ServerWorld;
import net.minecraft.util.math.*;
/** Real ticking train/driver checks, with two directions and six station stops on a closed curve. */
final class RailNetworkChecks {
 static RailVehicleEntity a,b;static int stage,ticks,deathAt;static UUID deadDriver;static boolean done;static double before;static net.minecraft.server.network.ServerPlayerEntity player;static int controlAt;
 static void require(boolean v,String why){if(!v)throw new AssertionError(why);}
 static List<Vec3d> circle(Vec3d center,double r){var out=new ArrayList<Vec3d>();double k=.5522847498307936;for(int i=0;i<4;i++){double theta=i*Math.PI/2;var p=center.add(r*Math.cos(theta),0,r*Math.sin(theta));var q=center.add(r*Math.cos(theta+Math.PI/2),0,r*Math.sin(theta+Math.PI/2));out.addAll(List.of(p,p.add(-r*k*Math.sin(theta),0,r*k*Math.cos(theta)),q.subtract(new Vec3d(-r*k*Math.sin(theta+Math.PI/2),0,r*k*Math.cos(theta+Math.PI/2))),q));}return out;}
 static void register(){if(!Boolean.getBoolean("halloween.railNetworkTest"))return;
  ServerTickEvents.END_SERVER_TICK.register(server->{if(done||server.getTicks()<40)return;var w=server.getOverworld();try{
   if(stage==0){for(int x=-9;x<=9;x++)for(int z=-9;z<=9;z++)w.setChunkForced(x,z,true);server.getTickManager().setTickRate(1000);var path=new RailPath(circle(new Vec3d(0,160,0),80));require(path.closed,"closed route detected");require(path.center(-.1).distanceTo(path.center(path.length-.1))<1e-5,"tail wraps across route seam");require(path.tangent(0).dotProduct(path.tangent(path.length-.01))>.999,"smooth tangent across loop seam");a=RailwayNetwork.spawnTrain(w,path,-4,20,1).getFirst();var reverse=path.reversed();b=RailwayNetwork.spawnTrain(w,reverse,-4,reverse.wrap(path.length-20),1).getFirst();var stops=new ArrayList<Double>();for(int i=0;i<6;i++)stops.add(path.length*i/6);a.setStops(stops);b.setStops(stops);a.dwell=0;b.dwell=0;stage=1;
   }
   ticks++;require(a.direction==1&&b.direction==1,"both engines keep travelling nose first, never reverse at a stop");
   if(stage==1&&a.visits>=7&&b.visits>=7){var driver=RailDriver.seat(w,a);require(driver!=null&&driver.getFirstPassenger() instanceof VillagerEntity,"persistent driver occupies control chair");var npc=(VillagerEntity)driver.getFirstPassenger();require(!VillageDefense.isGuard(npc)&&npc.getVillagerData().profession().equals(RailDriver.PROFESSION),"driver cannot be assigned guard profession");deadDriver=npc.getUuid();npc.damage(w,w.getDamageSources().genericKill(),10000);deathAt=ticks;before=a.distance;a.dwell=0;a.speed=.72;stage=2;log("PASS: both directions completed all six stations and crossed loop seam nose-first");}
   if(stage==2&&ticks-deathAt>180){require(a.speed==0,"engine brakes to standstill without a driver");require(RailDriver.seat(w,a)==null,"killed driver is not silently replaced");require(a.distance-before<30,"braking distance is finite");var data=WorldSettlements.get(w);for(int i=0;i<6;i++)WorldSettlements.discover(w,new BlockPos(i*700,70,0));require(data.cities.size()>=6,"global city catalogue");double low=Double.MAX_VALUE,high=0;for(var city:data.cities){double p=WorldSettlements.estimate(w,city);low=Math.min(low,p);high=Math.max(high,p);require(WorldSettlements.population(w,city)>=22,"plausible stable city population");}require(high-low<=.33,"city development differs modestly");require(!RailTravel.policeRoll(1,0)&&RailTravel.policeRoll(2,.299)&&!RailTravel.policeRoll(2,.30),"arrival police probability has exact 30% threshold and two-star minimum");String report=WorldStatistics.report(w);require(report.split("\f").length==3,"world almanac has three tabs");log("PASS: no early replacement, engine brakes; world progress/population and police thresholds");
    player=new net.minecraft.server.network.ServerPlayerEntity(server,w,new com.mojang.authlib.GameProfile(UUID.randomUUID(),"EngineDriverTest"),net.minecraft.network.packet.c2s.common.SyncedClientOptions.createDefault());player.networkHandler=new net.minecraft.server.network.ServerPlayNetworkHandler(server,new net.minecraft.network.ClientConnection(net.minecraft.network.NetworkSide.SERVERBOUND),player,net.minecraft.server.network.ConnectedClientData.createDefault(player.getGameProfile(),false));player.setPosition(a.getEntityPos().add(RailGeometry.rotate(RailDriver.CHAIR.add(0,-.55,0),a.getYaw())));w.onPlayerConnected(player);
    double throttle=a.throttle;RailControlNetwork.apply(player,new RailControlNetwork.Input(1,false));require(a.throttle==throttle,"unseated player cannot control train");require(a.interact(player,net.minecraft.util.Hand.MAIN_HAND)==net.minecraft.util.ActionResult.SUCCESS,"player can occupy dead driver's control chair");controlAt=ticks;before=a.distance;stage=3;
   }
   if(stage==3){RailControlNetwork.apply(player,new RailControlNetwork.Input(1,false));var seat=(RailSeatEntity)player.getVehicle();var local=RailPassengerNetwork.toLocal(a,player.getEntityPos());require(local.squaredDistanceTo(RailDriver.CHAIR.add(0,-.80,0))<.04,"mounted driver stays at chair, not floating a block ahead: "+local);require(seat.renderedPassengerPos(player,1).squaredDistanceTo(player.getEntityPos())<.0001,"rendered rider and physical seat share the same attachment transform");if(ticks-controlAt>120){require(a.speed>.2&&a.distance>before+4,"player accelerates engine through validated controls");controlAt=ticks;stage=4;}}
   if(stage==4){RailControlNetwork.apply(player,new RailControlNetwork.Input(0,true));if(ticks-controlAt>90){require(a.speed==0,"player brake stops engine");require(player.isAlive()&&player.getHealth()==20,"player driver remains alive and undamaged");player.stopRiding();w.removePlayer(player,Entity.RemovalReason.DISCARDED);log("PASS: player occupies special chair, accelerates and brakes; correct mounted position; no passenger damage");controlAt=ticks;stage=5;}}
   if(stage==5){if(ticks-controlAt<1180)require(RailDriver.seat(w,a)==null,"no replacement before a full minute without a controller");if(ticks-controlAt>1260){var chair=RailDriver.seat(w,a);require(chair!=null&&chair.getFirstPassenger() instanceof VillagerEntity,"new driver appears after a minute with an empty control chair");var replacement=(VillagerEntity)chair.getFirstPassenger();require(!replacement.getUuid().equals(deadDriver)&&replacement.getVillagerData().profession().equals(RailDriver.PROFESSION)&&!VillageDefense.isGuard(replacement),"replacement is a new ordinary train driver");require(a.speed>0,"replacement driver restarts stranded train");log("PASS: empty engine receives a new driver after 60 seconds, never while player is controlling it; train resumes");done=true;server.stop(false);}}
   if(ticks>26000)throw new AssertionError("six-stop circuit did not complete: "+a.visits+"/"+b.visits+" speed="+a.speed);
  }catch(Throwable e){done=true;org.slf4j.LoggerFactory.getLogger("rail-network-test").error("FAIL",e);server.stop(false);}});
 }
 static void log(String s){org.slf4j.LoggerFactory.getLogger("rail-network-test").info(s);}
}
